     "ts": 1789101534,
     "summary": "据英国《金融时报》今天（9月11日）报道，海湾国家外长计划与伊朗外长阿拉格齐举行会晤。此次会议由阿曼与伊朗牵头，旨在争取各方支持一项临时协议，以管控霍尔木兹海峡的航运秩序。报道援引两名知情人士的话称，会议定于下周一（9月14日）在阿曼沿海城市塞拉莱举行。（CCTV国际时讯）（文章来源：界面新闻）",
